def code_to_flag(code: str) -> str:
    return "".join(chr(127397 + ord(c)) for c in code.upper())

def build_file():
    code_lines = [
        '"""',
        'All Sovereign World Nations & Capital Metros Dataset',
        'Covers all 193 UN member states, Vatican City, Palestine, and sovereign jurisdictions.',
        '"""',
        '',
        'from typing import List, Dict, Any',
        '',
        'ALL_SOVEREIGN_WORLD_CITIES: List[Dict[str, Any]] = ['
    ]

    for item in COUNTRIES_DATA:
        dist_objs = [{"id": f"{item['code']}-{i+1:02d}", "name": d} for i, d in enumerate(item["districts"])]
        flag_val = code_to_flag(item["code"])
        entry = {
            "city_name": item["city"],
            "country": item["country"],
            "country_code": item["code"],
            "flag": flag_val,
            "region": item["region"],
            "population_millions": item["pop"],
            "lat": item["lat"],
            "lng": item["lng"],
            "crime_index": item["crime"],
            "safety_index": item["safe"],
            "crime_rate_per_100k": item["c_rate"],
            "violent_crime_rate_per_100k": item["v_rate"],
            "risk_tier": item["risk"],
            "emergency_number": item["em"],
            "police_agency": item["agency"],
            "is_live_db": False,
            "districts": dist_objs
        }
        entry_str = json.dumps(entry, indent=8, ensure_ascii=False).strip().replace("false", "False").replace("true", "True")
        code_lines.append(f"    {entry_str},")

    code_lines.append(']')
    code_lines.append('')

    with open("backend/global_all_countries.py", "w", encoding="utf-8") as f:
        f.write("\n".join(code_lines))

    print(f"Generated backend/global_all_countries.py with {len(COUNTRIES_DATA)} countries!")

if __name__ == "__main__":
    build_file()
